-- Add optional transfer exercises; preserve all existing mandatory IDs and learner history.
create temporary table varied_dataset_seed (payload jsonb) on commit drop;
insert into varied_dataset_seed values ($datasets$[{"slug": "membaca-bentuk-data", "type": "PSEUDOCODE", "title": "Baca struktur katalog buku", "prompt": "Pada Katalog Buku, mana pasangan kolom dan nilai yang benar?", "starter_code": null, "config": {"public": {"mode": "choice", "options": [{"id": "value", "text": "Dasar Basis Data adalah kolom; title adalah nilainya."}, {"id": "column", "text": "title adalah kolom; Dasar Basis Data adalah salah satu nilainya."}, {"id": "record", "text": "stock adalah satu record lengkap."}], "datasetId": "library", "subtopic": "Transfer konsep"}, "answer": {"choiceId": "column"}, "feedback": {"correct": "Tepat. Konsep yang sama berlaku pada skema berbeda.", "retry": "Bandingkan nama atribut pada header books dengan isi record book_id 10."}}}, {"slug": "key-dan-hubungan-antar-tabel", "type": "PSEUDOCODE", "title": "Ikuti detail pesanan Nadia", "prompt": "Nadia memiliki order #100 dan #300. Mengapa satu order dapat memiliki beberapa produk?", "starter_code": null, "config": {"public": {"mode": "choice", "options": [{"id": "direct", "text": "customers menyimpan semua produk pada kolom name."}, {"id": "detail", "text": "order_items merujuk order_id dan product_id; setiap baris adalah satu detail produk dalam pesanan."}, {"id": "position", "text": "Baris pertama setiap tabel selalu saling berhubungan."}], "datasetId": "shop", "subtopic": "Transfer konsep"}, "answer": {"choiceId": "detail"}, "feedback": {"correct": "Tepat. Konsep yang sama berlaku pada skema berbeda.", "retry": "Ikuti orders #100 ke order_items, lalu periksa product_id pada detailnya."}}}, {"slug": "memilih-sumber-dan-kolom", "type": "PREDICT_OUTPUT", "title": "Pilih dua kolom katalog", "prompt": "Prediksi judul dan stok buku, urut berdasarkan book_id.", "starter_code": "SELECT title, stock FROM books ORDER BY book_id;", "config": {"public": {"columns": ["title", "stock"], "datasetId": "library", "subtopic": "Transfer konsep"}, "answer": {"output": "Dasar Basis Data | 5\nLogika Data | 0\nAlgoritma Ringkas | 3\nPengantar SQL | 2"}, "grading": {"mode": "table", "columnTypes": ["text", "number"]}, "feedback": {"correct": "Tepat. Hubungkan hasilnya dengan record sumber pada skema ini.", "retry": "FROM menentukan books; SELECT hanya menampilkan title dan stock, bukan author_id."}}}, {"slug": "menyaring-record", "type": "PREDICT_OUTPUT", "title": "Temukan stok yang cukup", "prompt": "Prediksi buku dengan stock >= 3. Perhatikan buku tepat pada batas 3.", "starter_code": "SELECT title, stock FROM books WHERE stock >= 3 ORDER BY book_id;", "config": {"public": {"columns": ["title", "stock"], "datasetId": "library", "subtopic": "Transfer konsep"}, "answer": {"output": "Dasar Basis Data | 5\nAlgoritma Ringkas | 3"}, "grading": {"mode": "table", "columnTypes": ["text", "number"]}, "feedback": {"correct": "Tepat. Hubungkan hasilnya dengan record sumber pada skema ini.", "retry": "Periksa semua nilai stock. Nilai 3 termasuk karena menggunakan >=, bukan >."}}}, {"slug": "mengurutkan-dan-membatasi", "type": "PREDICT_OUTPUT", "title": "Bandingkan harga produk", "prompt": "Prediksi dua produk termahal. Harga diurutkan menurun sebelum LIMIT.", "starter_code": "SELECT name, price FROM products ORDER BY price DESC, product_id ASC LIMIT 2;", "config": {"public": {"columns": ["name", "price"], "datasetId": "shop", "subtopic": "Transfer konsep"}, "answer": {"output": "Tas | 80000\nBuku Catatan | 15000"}, "grading": {"mode": "table", "columnTypes": ["text", "number"]}, "feedback": {"correct": "Tepat. Hubungkan hasilnya dengan record sumber pada skema ini.", "retry": "Urutkan price dari terbesar terlebih dahulu; LIMIT tidak memilih dua record awal dari seed."}}}, {"slug": "menghubungkan-tabel", "type": "PREDICT_OUTPUT", "title": "Temukan semua buku Rani", "prompt": "Prediksi buku yang author_id-nya merujuk Rani. Satu penulis bisa muncul pada beberapa baris hasil.", "starter_code": "SELECT a.name, b.title FROM authors AS a JOIN books AS b ON b.author_id = a.author_id WHERE a.author_id = 1 ORDER BY b.book_id;", "config": {"public": {"columns": ["name", "title"], "datasetId": "library", "subtopic": "Transfer konsep"}, "answer": {"output": "Rani | Dasar Basis Data\nRani | Logika Data"}, "grading": {"mode": "table", "columnTypes": ["text", "text"]}, "feedback": {"correct": "Tepat. Hubungkan hasilnya dengan record sumber pada skema ini.", "retry": "Cocokkan books.author_id dengan authors.author_id; jangan memasangkan berdasarkan urutan baris."}}}, {"slug": "merangkum-data", "type": "PREDICT_OUTPUT", "title": "Hitung pesanan pelanggan", "prompt": "Prediksi jumlah order setiap pelanggan yang memiliki pesanan. COUNT menghitung order, bukan detail produk.", "starter_code": "SELECT c.name, COUNT(o.order_id) AS order_count FROM customers AS c JOIN orders AS o ON o.customer_id = c.customer_id GROUP BY c.customer_id, c.name ORDER BY c.customer_id;", "config": {"public": {"columns": ["name", "order_count"], "datasetId": "shop", "subtopic": "Transfer konsep"}, "answer": {"output": "Nadia | 2\nRaka | 1"}, "grading": {"mode": "table", "columnTypes": ["text", "number"]}, "feedback": {"correct": "Tepat. Hubungkan hasilnya dengan record sumber pada skema ini.", "retry": "Hitung orders per customer_id. INNER JOIN tidak menampilkan Lina yang belum memiliki order."}}}, {"slug": "tantangan-query-kampus", "type": "PREDICT_OUTPUT", "title": "Selidiki penjualan yang lunas", "prompt": "Prediksi jumlah unit setiap produk dari order berstatus paid. Jumlahkan quantity, bukan jumlah baris detail.", "starter_code": "SELECT p.name, SUM(i.quantity) AS total_quantity FROM products AS p JOIN order_items AS i ON i.product_id = p.product_id JOIN orders AS o ON o.order_id = i.order_id WHERE o.status = 'paid' GROUP BY p.product_id, p.name ORDER BY total_quantity DESC, p.product_id;", "config": {"public": {"columns": ["name", "total_quantity"], "datasetId": "shop", "subtopic": "Transfer konsep"}, "answer": {"output": "Pulpen | 5\nBuku Catatan | 2"}, "grading": {"mode": "table", "columnTypes": ["text", "number"]}, "feedback": {"correct": "Tepat. Hubungkan hasilnya dengan record sumber pada skema ini.", "retry": "Hanya order #100 dan #300 yang paid. Gunakan SUM(quantity), lalu urutkan total_quantity menurun."}}}, {"slug": "menambahkan-record-dengan-insert", "type": "PSEUDOCODE", "title": "Jaga rujukan buku baru", "prompt": "Untuk menambahkan book_id 50, author_id mana tersedia pada seed Katalog Buku?", "starter_code": null, "config": {"public": {"mode": "choice", "options": [{"id": "valid", "text": "3, karena authors memuat penulis Sinta dengan author_id 3."}, {"id": "title", "text": "50, karena sama dengan identitas buku baru."}, {"id": "missing", "text": "99, karena database otomatis membuat penulis yang belum ada."}], "datasetId": "library", "subtopic": "Transfer konsep"}, "answer": {"choiceId": "valid"}, "feedback": {"correct": "Tepat. Konsep yang sama berlaku pada skema berbeda.", "retry": "Foreign key buku harus menunjuk record authors yang sudah ada. ID buku dan penulis berbeda fungsi."}}}, {"slug": "mengubah-record-dengan-update", "type": "PSEUDOCODE", "title": "Ubah satu detail pesanan", "prompt": "Detail item_id 2 perlu quantity 4. Mana langkah aman sebelum menerapkan UPDATE?", "starter_code": null, "config": {"public": {"mode": "choice", "options": [{"id": "all", "text": "UPDATE order_items SET quantity = 4 tanpa WHERE."}, {"id": "product", "text": "Ubah semua detail dengan product_id = 20."}, {"id": "preview", "text": "Periksa item_id 2, pratinjau UPDATE dengan WHERE item_id = 2, lalu konfirmasi satu record."}], "datasetId": "shop", "subtopic": "Transfer konsep"}, "answer": {"choiceId": "preview"}, "feedback": {"correct": "Tepat. Konsep yang sama berlaku pada skema berbeda.", "retry": "Produk Pulpen muncul di dua detail pesanan. Gunakan PK item_id agar hanya satu record berubah."}}}, {"slug": "menghapus-record-dengan-delete", "type": "PSEUDOCODE", "title": "Hapus buku, pertahankan penulis", "prompt": "Logika Data (book_id 20) dikeluarkan dari katalog. Apa dampak DELETE books WHERE book_id = 20 setelah dikonfirmasi?", "starter_code": null, "config": {"public": {"mode": "choice", "options": [{"id": "author", "text": "Rani dan semua bukunya ikut dihapus."}, {"id": "one", "text": "Satu buku dihapus; authors dan buku Rani lainnya tetap ada."}, {"id": "schema", "text": "Kolom title dihapus dari schema books."}], "datasetId": "library", "subtopic": "Transfer konsep"}, "answer": {"choiceId": "one"}, "feedback": {"correct": "Tepat. Konsep yang sama berlaku pada skema berbeda.", "retry": "DELETE menghapus record target, bukan kolom atau otomatis menghapus record induknya."}}}]$datasets$::jsonb);

do $guard$
begin
 if (select count(*) from public.lessons l join public.chapters c on c.id=l.chapter_id join public.learning_paths p on p.id=c.learning_path_id where p.slug='database-fundamentals' and l.is_published)<>11 then raise exception 'Expected 11 published lessons'; end if;
 if exists (select 1 from public.exercises e join public.lessons l on l.id=e.lesson_id join public.chapters c on c.id=l.chapter_id join public.learning_paths p on p.id=c.learning_path_id where p.slug='database-fundamentals' and e.position=4 and e.is_required) then raise exception 'Position 4 must not replace mandatory practice'; end if;
end $guard$;

insert into public.exercises(lesson_id,type,title,prompt,starter_code,config,position,is_required,is_published)
select l.id,(x->>'type')::public.exercise_type,x->>'title',x->>'prompt',x->>'starter_code',x->'config',4,false,true
from varied_dataset_seed s cross join lateral jsonb_array_elements(s.payload) x
join public.lessons l on l.slug=x->>'slug'
join public.chapters c on c.id=l.chapter_id
join public.learning_paths p on p.id=c.learning_path_id
where p.slug='database-fundamentals' and l.is_published
on conflict (lesson_id,position) do update set type=excluded.type,title=excluded.title,prompt=excluded.prompt,starter_code=excluded.starter_code,config=excluded.config,is_required=false,is_published=true;

update public.lessons l
set content=replace(content,'Practice terakhir wajib untuk membuka materi berikutnya.','Practice berlabel Wajib membuka materi berikutnya; latihan konteks lain bersifat opsional.') ||
 case when content like '%## Coba skema lain%' then '' else E'\n\n## Coba skema lain\n\n' ||
 case when l.slug in ('membaca-bentuk-data','key-dan-hubungan-antar-tabel') then 'Bandingkan Kampus Mini dengan Katalog Buku dan Toko Mini pada penjelajah tabel di bawah. Perhatikan bahwa jumlah tabel dan jalur key-nya berbeda. Latihan konteks lain menguji konsep yang sama tanpa menambah syarat progres.'
 else 'Pada lab, pilih skema lain untuk menerapkan konsep yang sama pada katalog buku atau toko. Setiap skema memakai data fiktif tersendiri dan dimulai ulang saat diganti. Latihan konteks lain bersifat opsional; contoh utama dan practice wajib tetap memakai data kampus.' end end
from public.chapters c, public.learning_paths p
where l.chapter_id=c.id and c.learning_path_id=p.id and p.slug='database-fundamentals' and l.is_published;

do $verify$
begin
 if exists (select l.id from public.lessons l join public.chapters c on c.id=l.chapter_id join public.learning_paths p on p.id=c.learning_path_id left join public.exercises e on e.lesson_id=l.id and e.is_published where p.slug='database-fundamentals' and l.is_published group by l.id having count(e.id)<>4 or count(e.id) filter(where e.is_required)<>1) then raise exception 'Expected three optional and one mandatory exercise per lesson'; end if;
 if exists (select 1 from public.exercises e join public.lessons l on l.id=e.lesson_id join public.chapters c on c.id=l.chapter_id join public.learning_paths p on p.id=c.learning_path_id where p.slug='database-fundamentals' and e.is_published and (e.public_config ? 'answer' or e.public_config ? 'grading' or e.public_config ? 'feedback')) then raise exception 'Private grading fields exposed'; end if;
end $verify$;
